import numpy as np
L=open('answer.xyz').read().split('\n')
n=int(L[0]); at=[];xyz=[]
for l in L[2:2+n]:
    p=l.split(); at.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
for i in [0,6]:
    for j in range(n):
        d=np.linalg.norm(xyz[i]-xyz[j])
        if 0<d<3.2: print(i,at[i],j,at[j],round(d,2))
